/* ===================== BÀI 4 · Chương trình đầu tiên và debugger ===================== */
/* Bài 4 · Chương trình đầu tiên và debugger (AMTS-EMB-002-M01-L04, X86-004) — sinh bởi tools/author/mpu8086/l04.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P4=[{"label": "Ví dụ: chương trình đầu tiên in một dòng", "code": "; Ví dụ 1: chương trình đầu tiên, in một dòng chữ\n        .MODEL  SMALL                   ; chương trình .EXE: mã, dữ liệu riêng\n        .STACK  100H                    ; ngăn xếp 256 byte\n        .DATA\nmsg     DB      'Xin chao 8086!', 0DH, 0AH, '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA               ; 1. nạp DS = đoạn dữ liệu\n        MOV     DS, AX\n        MOV     AH, 09H                 ; 2. in chuỗi DS:DX tới dấu $\n        MOV     DX, OFFSET msg\n        INT     21H\n        MOV     AX, 4C00H               ; 3. trả quyền cho DOS, mã thoát 0\n        INT     21H\nMAIN    ENDP\n        END     MAIN                    ; điểm vào: nhãn MAIN\n", "input": "", "note": "Chương trình đầu tiên. Bấm Từng bước: sau MOV DS, AX, DS đổi từ 0700h (PSP) thành 0712h (đoạn dữ liệu, giả định của trình mô phỏng). INT 21h hàm 09h in tới byte 24h, kể cả CR LF. Đoán trước: sau lệnh MOV DX, OFFSET msg, DX bằng bao nhiêu? Đáp án 0000h (msg ở đầu đoạn dữ liệu)."}, {"label": "Lỗi: chuỗi cho hàm 09h thiếu dấu $", "code": "; Lỗi: chuỗi thiếu dấu $ ở cuối\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'Xin chao'              ; thiếu '$'\nso      DB      5\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 09H                 ; in tới khi gặp byte 24h ('$')\n        MOV     DX, OFFSET msg\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi: msg không có dấu $. Hàm 09h in “Xin chao”, rồi in tiếp biến so (byte 05h, hiện thành ký hiệu ♣ theo bảng mã của màn hình), rồi mọi byte phía sau. Trình mô phỏng dừng sau 4000 ký tự và báo lỗi; DOS thật in rác tới khi tình cờ gặp byte 24h. Sửa: thêm , '$' sau chuỗi. Đoán trước: ngay sau “Xin chao”, byte nào được in tiếp? Đáp án 05h (biến so)."}, {"label": "Lỗi: quên nạp DS, in nhầm vùng PSP", "code": "; Lỗi: quên nạp DS, in nhầm vùng nhớ của PSP\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'Xin chao$'\n        .CODE\nMAIN    PROC\n; thiếu MOV AX, @DATA / MOV DS, AX\n        MOV     AH, 09H\n        MOV     DX, OFFSET msg          ; DX = 0000h, nhưng DS = đoạn PSP\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi: thiếu MOV AX, @DATA / MOV DS, AX. DX = 0000h vẫn đúng là độ lệch của msg, nhưng DS = 0700h (PSP) nên hàm 09h in từ 0700:0000: byte CD 20 của PSP, các byte 0, rồi mã máy của chính chương trình, tới khi gặp dấu $ của msg ở 0711:0008 = 0700:0118. Chữ “Xin chao” chỉ hiện ở cuối, sau một dòng rác. Phần đầu (CD 20 …) không còn thấy vì byte 0Dh ở 0700:0081 (cuối dòng lệnh rỗng trong PSP) đưa con trỏ về đầu dòng, các byte sau ghi đè lên. Đoán trước: lúc gọi INT 21h, DS bằng bao nhiêu? Đáp án 0700h."}, {"label": "Ví dụ: INT 3 làm điểm dừng", "code": "; Ví dụ 4: INT 3 là điểm dừng cho debugger\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H\n        MOV     BX, 0ABCDH\n        INT     3                       ; dừng ở đây: xem AX, BX\n        XCHG    AX, BX                  ; đổi chỗ hai thanh ghi\n        INT     3                       ; dừng lần hai: AX, BX đã đổi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "INT 3 (mã máy CC, 1 byte, 52 chu kỳ) là điểm dừng: bấm Chạy, trình mô phỏng dừng sau mỗi INT 3, bấm Chạy tiếp để đi tiếp. Lần dừng đầu AX = 1234h, BX = ABCDh; lần hai đã đổi chỗ. XCHG AX, BX chỉ 1 byte (93h), 3 chu kỳ. Đoán trước: ở lần dừng thứ hai, AX bằng bao nhiêu? Đáp án ABCDh."}, {"label": "Ví dụ: lưu thanh ghi ra bộ nhớ rồi dump", "code": "; Ví dụ 5: lưu thanh ghi ra bộ nhớ để xem bằng dump\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nluu     DW      4 DUP(?)                ; ảnh chụp AX, BX, CX, DX\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234H\n        MOV     BX, AX\n        ADD     BX, BX                  ; BX = 2468h\n        MOV     CX, BX\n        SUB     CX, AX                  ; CX = 1234h\n        MOV     DX, 0FFFFH\n        MOV     luu, AX                 ; luu+0: 34 12\n        MOV     luu+2, BX               ; luu+2: 68 24\n        MOV     luu+4, CX               ; luu+4: 34 12\n        MOV     luu+6, DX               ; luu+6: FF FF\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ảnh chụp thanh ghi: bốn lệnh MOV ghi AX, BX, CX, DX vào luu. Xem phần Bộ nhớ (hoặc D luu L 8 ở Hình 4.2): 34 12 68 24 34 12 FF FF. Ở phần Mã máy và chu kỳ: MOV luu, AX là A3 00 00 (10 chu kỳ), ba lệnh sau là 89 xx (15 chu kỳ). Đoán trước: sau SUB CX, AX, CX bằng bao nhiêu? Đáp án 1234h."}, {"label": "Ví dụ: khung chương trình bare-metal", "code": "; Ví dụ 6: khung chương trình bare-metal (chạy thử)\n; Trên bo thật đoạn này nằm trong ROM, chạy sau RESET.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        CLI                             ; chưa có bảng vectơ ngắt: cấm ngắt\n        MOV     AX, 2000H               ; ngăn xếp tự đặt (giả định RAM)\n        MOV     SS, AX\n        MOV     SP, 0100H\n        MOV     AX, 2100H               ; vùng dữ liệu tự chọn\n        MOV     DS, AX\n        XOR     BX, BX\n        MOV     BYTE PTR [BX], 55H      ; dấu hiệu đã khởi động\n        MOV     AL, 1\nden:\n        OUT     0F0H, AL                ; cổng LED giả định\n        SHL     AL, 1                   ; đèn sáng dịch sang trái\n        JNC     den                     ; 8 lần, tới khi bit 1 ra CF\n        HLT                             ; bo thật: CPU dừng ở đây mãi\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Khung bare-metal (xem mục 4.4): CLI, tự đặt SS = 2000h, SP = 0100h, DS = 2100h (vùng RAM giả định), ghi 55h vào 2100:0000 = 21000h, rồi 8 lần OUT ra cổng F0h với AL = 01h, 02h, …, 80h. Lần thứ 8, SHL đẩy bit 1 ra CF nên JNC không nhảy (4 chu kỳ thay vì 16), gặp HLT. Không có INT 21h nào. Đoán trước: sau lần SHL cuối, AL bằng bao nhiêu? Đáp án 00h."}, {"label": "Bẫy: in số 7 bằng hàm 02h", "code": "; Bẫy: in số 7 bằng hàm 02h nhưng màn hình trống\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     DL, 3\n        ADD     DL, 4                   ; DL = 7, giá trị số\n        MOV     AH, 02H                 ; hàm 02h in KÝ TỰ có mã DL\n        INT     21H                     ; mã 07h là BEL, không phải '7'\n        ADD     DL, '0'                 ; sửa: 7 + 30h = 37h = '7'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: DL = 3 + 4 = 7 là giá trị số. Hàm 02h in ký tự có mã 07h, là BEL (chuông) chứ không phải chữ số 7, nên lần in đầu không hiện gì (trình mô phỏng bỏ qua BEL; DOS thật phát tiếng bíp). Cộng '0' (30h) được 37h, mã của chữ số 7. Đoán trước: sau ADD DL, '0', DL bằng bao nhiêu (hệ 16)? Đáp án 37h."}];
const sim4=makeX86Sim(document.getElementById("x86-l4"),{id:"s4",presets:P4,file:"BAI4.ASM"});
makeX86Ex(document.getElementById("ex-l4"),sim4,[{"t": "Chương trình đầu tiên có nhập", "d": "Đọc một phím bằng INT 21h hàm 08h (không hiện) và ghi mã ASCII vào biến phim. In chuỗi loi (Ban go: ) bằng hàm 09h, in chính phím đó bằng hàm 02h, rồi xuống dòng bằng hai ký tự 0Dh, 0Ah. Ví dụ phím A: màn hình hiện Ban go: A. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: chương trình đầu tiên có nhập\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nloi     DB      'Ban go: $'             ; chuỗi cho hàm 09h, kết thúc bằng $\nphim    DB      ?                       ; mã ASCII của phím\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H\n        MOV     phim, AL\n; In loi bằng hàm 09h, rồi in phím bằng hàm 02h,\n; rồi xuống dòng: in 0Dh và 0Ah\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "A", "out": "Ban go: A\n", "mem": [{"at": "phim", "bytes": [65]}]}, {"dosExit": true, "in": "z", "out": "Ban go: z\n", "mem": [{"at": "phim", "bytes": [122]}]}, {"dosExit": true, "in": "7", "out": "Ban go: 7\n", "mem": [{"at": "phim", "bytes": [55]}]}, {"dosExit": true, "in": "$", "out": "Ban go: $\n", "mem": [{"at": "phim", "bytes": [36]}]}, {"dosExit": true, "in": " ", "out": "Ban go:  \n", "mem": [{"at": "phim", "bytes": [32]}]}, {"dosExit": true, "in": "~", "out": "Ban go: ~\n", "mem": [{"at": "phim", "bytes": [126]}]}]}, {"t": "In mã phím dạng hệ 16", "d": "Đọc một phím bằng INT 21h hàm 08h và in mã ASCII của nó bằng hai chữ số hệ 16 (chữ hoa) rồi chữ h, như cột byte của debugger. Ví dụ phím A (65): in 41h; phím z: in 7Ah. Code mẫu đã in chữ số cao bằng bảng hexso; hãy in thêm chữ số thấp và chữ h. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: in mã phím dạng hệ 16, như cột byte của debugger\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhexso   DB      '0123456789ABCDEF'      ; hexso[n] = chữ số hệ 16 của n\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H\n        MOV     BL, AL                  ; BX = mã phím (0–7Fh)\n        MOV     BH, 0\n        MOV     CL, 4\n        SHR     BX, CL                  ; BX = 4 bit cao\n        MOV     DL, hexso[BX]\n        MOV     AH, 02H\n        INT     21H                     ; in chữ số cao\n; Còn thiếu: chữ số thấp (4 bit thấp) và chữ h\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "A", "out": "41h"}, {"dosExit": true, "in": "z", "out": "7Ah"}, {"dosExit": true, "in": "0", "out": "30h"}, {"dosExit": true, "in": "~", "out": "7Eh"}, {"dosExit": true, "in": " ", "out": "20h"}, {"dosExit": true, "in": "?", "out": "3Fh"}]}, {"t": "Ảnh chụp nhanh bốn bội số", "d": "Đọc một phím bằng INT 21h hàm 08h, gọi k là mã ASCII (byte cao bằng 0). Ghi k, 2k, 3k, 4k vào bốn biến word a1, a2, a3, a4 (ví dụ phím A: 0041h, 0082h, 00C3h, 0104h). Code mẫu đúng nhưng ghi từ BX, CX, DX: mỗi lệnh ghi dài 4 byte, 15 chu kỳ. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: ảnh chụp bốn bội của mã phím (đúng nhưng chậm)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na1      DW      ?                       ; k\na2      DW      ?                       ; 2k\na3      DW      ?                       ; 3k\na4      DW      ?                       ; 4k\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím: AL = k\n        INT     21H\n        MOV     AH, 0                   ; AX = k\n        MOV     BX, AX\n        ADD     BX, AX                  ; BX = 2k\n        MOV     CX, BX\n        ADD     CX, AX                  ; CX = 3k\n        MOV     DX, CX\n        ADD     DX, AX                  ; DX = 4k\n        MOV     a1, AX\n        MOV     a2, BX\n        MOV     a3, CX\n        MOV     a4, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "A", "mem": [{"at": "a1", "bytes": [65, 0]}, {"at": "a2", "bytes": [130, 0]}, {"at": "a3", "bytes": [195, 0]}, {"at": "a4", "bytes": [4, 1]}]}, {"dosExit": true, "in": "z", "mem": [{"at": "a1", "bytes": [122, 0]}, {"at": "a2", "bytes": [244, 0]}, {"at": "a3", "bytes": [110, 1]}, {"at": "a4", "bytes": [232, 1]}]}, {"dosExit": true, "in": "~", "mem": [{"at": "a1", "bytes": [126, 0]}, {"at": "a2", "bytes": [252, 0]}, {"at": "a3", "bytes": [122, 1]}, {"at": "a4", "bytes": [248, 1]}]}, {"dosExit": true, "in": " ", "mem": [{"at": "a1", "bytes": [32, 0]}, {"at": "a2", "bytes": [64, 0]}, {"at": "a3", "bytes": [96, 0]}, {"at": "a4", "bytes": [128, 0]}]}, {"dosExit": true, "in": "0", "mem": [{"at": "a1", "bytes": [48, 0]}, {"at": "a2", "bytes": [96, 0]}, {"at": "a3", "bytes": [144, 0]}, {"at": "a4", "bytes": [192, 0]}]}, {"dosExit": true, "in": "!", "mem": [{"at": "a1", "bytes": [33, 0]}, {"at": "a2", "bytes": [66, 0]}, {"at": "a3", "bytes": [99, 0]}, {"at": "a4", "bytes": [132, 0]}]}], "perf": {"cycles": 175, "bytes": 38}}]);
/* Bảng lệnh debugger (Hình 4.2): chạy các ví dụ của bài (platform/js/59-x86-dbg.js, 59-x86-dbg-ui.js). */
makeX86Dbg(document.getElementById("xd-l4"),{id:"xd4",progs:[{"label": "Ví dụ 5: lưu thanh ghi rồi dump", "file": "VD05.EXE", "code": "; Ví dụ 5: lưu thanh ghi ra bộ nhớ để xem bằng dump\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nluu     DW      4 DUP(?)                ; ảnh chụp AX, BX, CX, DX\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234H\n        MOV     BX, AX\n        ADD     BX, BX                  ; BX = 2468h\n        MOV     CX, BX\n        SUB     CX, AX                  ; CX = 1234h\n        MOV     DX, 0FFFFH\n        MOV     luu, AX                 ; luu+0: 34 12\n        MOV     luu+2, BX               ; luu+2: 68 24\n        MOV     luu+4, CX               ; luu+4: 34 12\n        MOV     luu+6, DX               ; luu+6: FF FF\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "note": "Lab của bài: chạy từng lệnh, lưu thanh ghi, dump. Gợi ý: R, T 2 (DS đổi), U, G 22 (dừng trước MOV AX, 4C00h), D luu L 8.", "cmds": ["R", "T 2", "U", "G 22", "D luu L 8", "D SS:SP L 10"]}, {"label": "Ví dụ 1: chương trình đầu tiên", "file": "VD01.EXE", "code": "; Ví dụ 1: chương trình đầu tiên, in một dòng chữ\n        .MODEL  SMALL                   ; chương trình .EXE: mã, dữ liệu riêng\n        .STACK  100H                    ; ngăn xếp 256 byte\n        .DATA\nmsg     DB      'Xin chao 8086!', 0DH, 0AH, '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA               ; 1. nạp DS = đoạn dữ liệu\n        MOV     DS, AX\n        MOV     AH, 09H                 ; 2. in chuỗi DS:DX tới dấu $\n        MOV     DX, OFFSET msg\n        INT     21H\n        MOV     AX, 4C00H               ; 3. trả quyền cho DOS, mã thoát 0\n        INT     21H\nMAIN    ENDP\n        END     MAIN                    ; điểm vào: nhãn MAIN\n", "note": "So DS trước và sau T 2; D DS:0 L 18 cho thấy chuỗi và dấu $ ở cột ký tự.", "cmds": ["R", "T 2", "D DS:0 L 18", "T 3", "G"]}, {"label": "Ví dụ 4: INT 3 làm điểm dừng", "file": "VD04.EXE", "code": "; Ví dụ 4: INT 3 là điểm dừng cho debugger\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H\n        MOV     BX, 0ABCDH\n        INT     3                       ; dừng ở đây: xem AX, BX\n        XCHG    AX, BX                  ; đổi chỗ hai thanh ghi\n        INT     3                       ; dừng lần hai: AX, BX đã đổi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "note": "G chạy tới INT 3 thì dừng; R xem AX, BX; G lần nữa.", "cmds": ["G", "R", "G", "G", "L"]}, {"label": "Ví dụ 3: quên nạp DS", "file": "VD03.EXE", "code": "; Lỗi: quên nạp DS, in nhầm vùng nhớ của PSP\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'Xin chao$'\n        .CODE\nMAIN    PROC\n; thiếu MOV AX, @DATA / MOV DS, AX\n        MOV     AH, 09H\n        MOV     DX, OFFSET msg          ; DX = 0000h, nhưng DS = đoạn PSP\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "note": "R: DS = 0700h (PSP). D DS:0 L 20 là vùng hàm 09h sẽ in.", "cmds": ["R", "D DS:0 L 20", "D DS:110 L 10", "G"]}, {"label": "Ví dụ 6: khung bare-metal", "file": "VD06.EXE", "code": "; Ví dụ 6: khung chương trình bare-metal (chạy thử)\n; Trên bo thật đoạn này nằm trong ROM, chạy sau RESET.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        CLI                             ; chưa có bảng vectơ ngắt: cấm ngắt\n        MOV     AX, 2000H               ; ngăn xếp tự đặt (giả định RAM)\n        MOV     SS, AX\n        MOV     SP, 0100H\n        MOV     AX, 2100H               ; vùng dữ liệu tự chọn\n        MOV     DS, AX\n        XOR     BX, BX\n        MOV     BYTE PTR [BX], 55H      ; dấu hiệu đã khởi động\n        MOV     AL, 1\nden:\n        OUT     0F0H, AL                ; cổng LED giả định\n        SHL     AL, 1                   ; đèn sáng dịch sang trái\n        JNC     den                     ; 8 lần, tới khi bit 1 ra CF\n        HLT                             ; bo thật: CPU dừng ở đây mãi\nMAIN    ENDP\n        END     MAIN\n", "note": "Không có INT 21h. G liệt kê 8 lần OUT ra cổng F0h; D 2100:0 L 8 xem byte dấu hiệu.", "cmds": ["U", "T 9", "G", "D 2100:0 L 8"]}]});

makeQuiz("quiz4","score4",[{"q": "Chuỗi khai báo <code>msg DB 'Xin chao'<\/code> (không có dấu $) được in bằng INT 21h hàm 09h. Điều gì xảy ra?", "o": ["In đúng “Xin chao” vì trình dịch tự thêm dấu $ vào cuối", "In “Xin chao” rồi in tiếp các byte phía sau tới khi gặp byte 24h", "Trình dịch báo lỗi vì chuỗi cho hàm 09h phải có dấu $", "DOS báo lỗi và kết thúc chương trình ngay khi gọi INT 21h"], "a": 1, "e": "Hàm 09h không biết độ dài chuỗi, chỉ dừng ở byte 24h đầu tiên. Trình dịch không kiểm tra và không thêm gì (Ví dụ 2)."}, {"q": "Ngay sau RESET, 8086 nạp lệnh đầu tiên ở địa chỉ vật lý nào?", "o": ["FFFF0h, vì CS = FFFFh và IP = 0000h sau RESET", "00000h, vì mọi thanh ghi đều về 0 sau RESET", "00400h, ngay sau bảng vectơ ngắt 1 KB", "07100h, nơi DOS nạp chương trình .EXE"], "a": 0, "e": "RESET đặt CS = FFFFh, IP = 0, DS = SS = ES = 0: FFFFh × 16 + 0 = FFFF0h, còn 16 byte tới hết 1 MB nên ở đó thường là lệnh nhảy xa. 07100h là giả định của trình mô phỏng cho chương trình DOS."}, {"q": "Debugger cho hai dòng dump dưới đây (biến <code>luu DW 4 DUP(?)<\/code> ở 0713:0000). Word <code>luu+2<\/code> bằng bao nhiêu?<pre class=\"mp-asm\">0713:0000  34 12 68 24  4.h$\n0713:0004  34 12 FF FF  4...<\/pre>", "o": ["6824h, đọc hai byte theo thứ tự từ trái sang phải", "2468h, đọc byte cao 24 ở 0003 rồi byte thấp 68", "1234h, vì luu+2 là phần tử thứ hai, bằng AX", "3412h, vì word luôn bắt đầu ở độ lệch 0000"], "a": 1, "e": "8086 lưu word byte thấp trước (little-endian): byte ở 0002 là 68h (thấp), ở 0003 là 24h (cao) nên word là 2468h. luu+2 là độ lệch theo byte, tức phần tử word thứ hai."}, {"q": "Vì sao debugger dùng <code>INT 3<\/code> (mã máy <code>CC<\/code>) để đặt điểm dừng thay cho <code>INT 21h<\/code> hay <code>INT 5<\/code>?", "o": ["INT 3 chỉ dài 1 byte nên đè được lên byte đầu của mọi lệnh", "INT 3 chạy nhanh nhất trong các lệnh ngắt, chỉ tốn 3 chu kỳ", "INT 3 là lệnh duy nhất làm CPU xóa hàng đợi lệnh khi gặp", "Lệnh INT n với n khác 3 không được dùng trong chương trình EXE"], "a": 0, "e": "INT n là 2 byte (CD n): đè lên lệnh 1 byte sẽ lấn sang lệnh sau. INT 3 có mã riêng CC 1 byte; nó tốn 52 chu kỳ (hơn INT n 1 chu kỳ). Mọi INT, như mọi lệnh chuyển điều khiển, đều làm xóa hàng đợi."}, {"q": "Chương trình chạy trên bo 8086 không có hệ điều hành gọi <code>MOV AH, 09h<\/code> / <code>INT 21h<\/code> để in chữ. Kết quả là gì?", "o": ["In đúng chuỗi vì INT 21h là lệnh in có sẵn trong CPU 8086", "Trình dịch báo lỗi vì chương trình bare-metal không có INT", "CPU tự bỏ qua lệnh INT 21h khi chưa có hệ điều hành", "Không in gì đúng ý: không có DOS nên vectơ 21h trỏ tới nơi không phải dịch vụ in"], "a": 3, "e": "INT 21h chỉ là “nhảy theo vectơ 21h” (ô nhớ 00084h–00087h). Dịch vụ in là chương trình của DOS; trên bo không có DOS, vectơ đó là bất cứ gì có trong RAM (hoặc do chương trình tự điền). Bare-metal phải ghi cổng của chip ngoại vi."}]);

